def transform(grid):
    # Identify zero-valued pockets enclosed by 5-valued lines and the grid border.
    # The inferred intended recoloring is: tiny pockets become 7, larger pockets become 8.
    from collections import deque
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False]*w for _ in range(h)]
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or seen[r][c]:
                continue
            q=deque([(r,c)]); seen[r][c]=True; cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and grid[ny][nx]==0:
                        seen[ny][nx]=True; q.append((ny,nx))
            comps.append(cells)
    # Border-enclosed pockets: connected zero regions bounded by 5 walls and the edge.
    # Treat the largest exterior region as background; color other regions by their area.
    border = set()
    for comp in comps:
        if any(r==0 or c==0 or r==h-1 or c==w-1 for r,c in comp):
            border.add(id(comp))
    # Heuristic: only recolor zero regions with small-area boundary pockets, by area.
    for comp in comps:
        touches = any(r==0 or c==0 or r==h-1 or c==w-1 for r,c in comp)
        if touches and len(comp) <= max(1, h*w//3):
            color = 7 if len(comp) <= 2 else 8
            for r,c in comp: out[r][c]=color
    return out
